**Step 1.2: Implement Configuration Service**

```csharp
public class HierarchicalConfigurationService
{
    private readonly IConfigurationStore _store;
    private readonly IDistributedCache _cache;
    private readonly ITenantContextManager _tenantContext;
    private readonly IAuditLogger _auditLogger;

    public async Task<T> GetConfigurationAsync<T>(
        string key,
        ConfigurationScope scope = ConfigurationScope.Tenant)
    {
        var context = _tenantContext.GetCurrentTenant();
        var cacheKey = $"config:{scope}:{context.TenantId}:{key}";

        // Check cache first
        var cached = await _cache.GetAsync<T>(cacheKey);
        if (cached != null)
            return cached;

        // Load configuration hierarchy
        var global = await _store.GetGlobalConfigurationAsync(key);
        var product = await _store.GetProductConfigurationAsync(key);
        var tenant = await _store.GetTenantConfigurationAsync(
            context.TenantId, key);
        var user = await _store.GetUserConfigurationAsync(
            context.UserId, key);

        // Merge with precedence: user > tenant > product > global
        var merged = MergeConfigurations<T>(global, product, tenant, user);

        // Cache the result
        await _cache.SetAsync(cacheKey, merged, TimeSpan.FromMinutes(15));

        return merged;
    }

    private T MergeConfigurations<T>(
        params object[] configurations)
    {
        // Merge configurations with most specific taking precedence
        var result = Activator.CreateInstance<T>();

        foreach (var config in configurations.Where(c => c != null))
        {
            // Use reflection or JSON merge to combine configurations
            JsonConvert.PopulateObject(
                JsonConvert.SerializeObject(config),
                result);
        }

        return result;
    }

    public async Task SetTenantConfigurationAsync<T>(
        string tenantId, string key, T value)
    {
        // Validate configuration
        await ValidateConfigurationAsync(key, value);

        // Store configuration
        await _store.SetTenantConfigurationAsync(tenantId, key, value);

        // Invalidate cache
        await _cache.RemoveAsync($"config:*:{tenantId}:{key}");

        // Audit log
        await _auditLogger.LogConfigurationChangeAsync(
            tenantId, key, value);
    }
}
