#### Phase 2: Feature Flag Implementation (Weeks 4-6)

**Step 2.1: Implement Feature Flag Service**

```csharp
public class FeatureFlagService
{
    private readonly IConfigurationStore _configStore;
    private readonly ITenantContextManager _tenantContext;
    private readonly IDistributedCache _cache;

    public async Task<bool> IsFeatureEnabledAsync(string featureKey)
    {
        var context = _tenantContext.GetCurrentTenant();
        var cacheKey = $"feature:{featureKey}:{context.TenantId}:{context.UserId}";

        // Check cache
        var cached = await _cache.GetAsync<bool?>(cacheKey);
        if (cached.HasValue)
            return cached.Value;

        // Load feature flag configuration
        var flag = await _configStore.GetFeatureFlagAsync(featureKey);

        if (flag == null)
            return false;  // Feature doesn't exist

        // Check kill switch
        if (flag.KillSwitch)
            return false;

        // Evaluate targeting rules
        var enabled = await EvaluateTargetingRulesAsync(flag, context);

        // Cache result
        await _cache.SetAsync(cacheKey, enabled, TimeSpan.FromMinutes(5));

        return enabled;
    }

    private async Task<bool> EvaluateTargetingRulesAsync(
        FeatureFlag flag, TenantContext context)
    {
        // Check tenant allowlist
        if (flag.TenantAllowlist != null)
        {
            return flag.TenantAllowlist.Contains(context.TenantId);
        }

        // Check percentage rollout
        if (flag.PercentageRollout > 0)
        {
            var hash = ComputeHash(flag.Key, context.TenantId, context.UserId);
            var percentage = (hash % 100) + 1;

            if (percentage > flag.PercentageRollout)
                return false;
        }

        // Evaluate complex targeting rules
        if (flag.TargetingRules != null)
        {
            foreach (var rule in flag.TargetingRules)
            {
                if (await EvaluateRuleAsync(rule, context))
                    return rule.Enabled;
            }
        }

        // Default to flag's default value
        return flag.DefaultEnabled;
    }
}

public class FeatureFlag
{
    public string Key { get; set; }
    public string Name { get; set; }
    public string Description { get; set; }
    public bool DefaultEnabled { get; set; }
    public bool KillSwitch { get; set; }

    // Targeting strategies
    public List<string> TenantAllowlist { get; set; }
    public int PercentageRollout { get; set; }  // 0-100
    public List<TargetingRule> TargetingRules { get; set; }

    // Metadata
    public DateTime CreatedDate { get; set; }
    public string Owner { get; set; }
    public List<string> Tags { get; set; }
}

public class TargetingRule
{
    public string RuleId { get; set; }
    public string Condition { get; set; }  // Expression to evaluate
    public bool Enabled { get; set; }  // Result if condition matches
    public int Priority { get; set; }  // Evaluation order
}
```

**Step 2.2: Feature Flag Code Integration**

```csharp
public class PatientService
{
    private readonly IFeatureFlagService _featureFlags;
    private readonly IPatientRepository _patients;

    public async Task<PatientDetails> GetPatientDetailsAsync(string patientId)
    {
        var patient = await _patients.GetByIdAsync(patientId);

        // Use feature flag to control new feature
        if (await _featureFlags.IsFeatureEnabledAsync("enhanced-patient-view"))
        {
            // Load additional patient data for enhanced view
            patient.SocialDeterminants = await LoadSocialDeterminantsAsync(patientId);
            patient.CareGaps = await LoadCareGapsAsync(patientId);
        }

        return patient;
    }
}
